// Combine campaign strategy and competitor data
const campaignData = $input.first().json;
const competitorData = $input.last().json;

const optimizedStrategy = {
  campaign_id: 'camp_' + Date.now(),
  client: campaignData.client_info,
  strategy: {
    recommended_platforms: campaignData.recommended_platforms,
    budget_allocation: campaignData.budget_allocation,
    keyword_strategy: campaignData.keyword_strategy,
    competitor_insights: competitorData.insights
  },
  optimization_recommendations: {
    bid_adjustments: campaignData.bid_recommendations,
    audience_targeting: campaignData.audience_strategy,
    competitive_advantages: competitorData.opportunities
  },
  expected_performance: {
    estimated_ctr: campaignData.estimated_ctr,
    projected_roas: campaignData.projected_roas,
    monthly_impressions: campaignData.impression_forecast
  }
};

return { json: optimizedStrategy };

// Launch campaigns automatically
const campaignData = $json;

// Simulate campaign launch across platforms
const launchedCampaigns = campaignData.campaigns.map(campaign => ({
  ...campaign,
  status: 'live',
  launched_at: new Date().toISOString(),
  initial_bid_strategy: 'ai_optimized',
  monitoring_enabled: true
}));

return {
  json: {
    status: 'campaigns_launched',
    campaigns: launchedCampaigns,
    total_campaigns: launchedCampaigns.length,
    estimated_daily_spend: campaignData.daily_budget,
    optimization_schedule: '4x_daily',
    next_review: new Date(Date.now() + 6 * 60 * 60 * 1000).toISOString()
  }
};

// Queue for manual review
const campaignData = $json;

return {
  json: {
    status: 'pending_review',
    campaigns: campaignData.campaigns,
    review_required: true,
    review_url: `https://dashboard.six3.agency/campaigns/review/${campaignData.campaign_id}`,
    estimated_review_time: '2-4 hours',
    expires_at: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString()
  }
};

// Aggregate results and create response
const results = $input.all();
const campaignResult = results[0].json;

const response = {
  success: true,
  service: 'Search Marketing & Paid Media',
  campaign_status: campaignResult.status,
  summary: {
    total_campaigns: campaignResult.campaigns?.length || campaignResult.total_campaigns,
    platforms_used: campaignResult.campaigns?.map(c => c.platform) || [],
    optimization_type: 'AI-Driven',
    performance_tracking: 'Real-time'
  },
  next_steps: campaignResult.status === 'campaigns_launched' 
    ? ['Monitor performance', 'Automated optimization active', 'Weekly performance review']
    : ['Await manual review', 'Campaign refinement', 'Launch approval'],
  dashboard_url: 'https://dashboard.six3.agency/search-marketing',
  estimated_results: {
    time_to_impact: '24-48 hours',
    optimization_frequency: '4x daily',
    reporting_schedule: 'Daily + Weekly'
  }
};

return { json: response };
